// =============================================================================
// Stack Component - Navigation-style card manager
// =============================================================================

// Provider & Hooks
export {
	CardStackProvider,
	useCardStack,
	useStackContext,
	useStackLayoutMode,
	useStackCards,
	useIsTopCard,
	useCardIndex,
	useCardInjectedProps,
	useCardReady,
} from '@/components/ui/stack/stack-context';

// Viewport
export { CardStackViewport } from '@/components/ui/stack/stack-viewport';

// Sub-components (for customization)
export { StackBackdrop, type StackBackdropProps } from '@/components/ui/stack/stack-backdrop';
export { StackHeader, StackHeaderSlot, type StackHeaderProps, type StackHeaderSlotProps } from '@/components/ui/stack/stack-header';
export { StackCard, type StackCardProps } from '@/components/ui/stack/stack-card';
export { DeferredCardContent, type DeferredCardContentProps } from '@/components/ui/stack/deferred-card-content';

// Hooks
export { useStackResponsive, useIsMobile, type UseStackResponsiveResult } from '@/components/ui/stack/use-stack-responsive';
export { useStackGestures, type UseStackGesturesResult } from '@/components/ui/stack/use-stack-gestures';
export { usePeekGestures, type UsePeekGesturesOptions, type UsePeekGesturesResult } from '@/components/ui/stack/use-peek-gestures';

// Utilities
export {
	getCascadeOffset,
	getSideBySideOffset,
	getCardOffset,
	getResponsiveCardOffset,
	calculateResponsiveOffset,
	normalizeWidth,
	parseWidthToPixels,
	getCardZIndex,
	getVisibleCardIndices,
	isCardVisible,
	type ResponsiveOffsetConfig,
	type ResponsiveOffsetResult,
} from '@/components/ui/stack/stack-utils';

// Animation utilities
export {
	DEFAULT_ANIMATION_CONFIG,
	createCardVariants,
	createEnterTransition,
	createExitTransition,
	createOffsetTransition,
	backdropVariants,
	snapBackSpring,
	swipeDismissTransition,
	peekHoverSpring,
	peekDragSpring,
	peekSlideSpring,
	createReducedMotionVariants,
	reducedMotionBackdropVariants,
} from '@/components/ui/stack/stack-animations';

// Types
export type {
	// Core
	CardId,
	CardComponent,
	CardInjectedProps,
	CardSpec,
	BackdropConfig,
	// Routes
	CardRouteDefinition,
	CardRouteMap,
	// Layout
	LayoutMode,
	// API
	CardStackApi,
	DismissOptions,
	PushOptions,
	CardPushOptions,
	// Props
	CardStackProviderProps,
	CardStackViewportProps,
	AnimationConfig,
	GestureConfig,
	PeekGestureConfig,
	MobileConfig,
	// Internal (for advanced customization)
	StackState,
	StackAction,
	StackContextValue,
} from '@/components/ui/stack/stack.types';

'use client';

import * as React from 'react';
import { createContext, useContext, useEffect, useMemo, useReducer, useRef, useState } from 'react';

import type {
  CardId,
  CardPushOptions,
  CardSpec,
  CardStackApi,
  CardStackProviderProps,
  DismissOptions,
  LayoutMode,
  PushOptions,
  StackAction,
  StackContextValue,
  StackState,
} from '@/components/ui/stack/stack.types';

// =============================================================================
// Constants
// =============================================================================

const DEFAULT_Z_INDEX_BASE = 100;
const DEFAULT_PEEK_OFFSET = 48;
const DEFAULT_WIDTH = 480;

// =============================================================================
// Reducer
// =============================================================================

function stackReducer(state: StackState, action: StackAction): StackState {
  switch (action.type) {
    case 'PUSH': {
      // Remove existing card with same ID to prevent duplicates
      const filtered = state.cards.filter((c) => c.id !== action.card.id);
      return { cards: [...filtered, action.card] };
    }

    case 'POP': {
      const count = Math.max(1, action.count);
      if (state.cards.length === 0) return state;
      return { cards: state.cards.slice(0, -count) };
    }

    case 'POP_TO': {
      const index = state.cards.findIndex((c) => c.id === action.id);
      if (index === -1) return state;
      return { cards: state.cards.slice(0, index + 1) };
    }

    case 'REPLACE_TOP': {
      if (state.cards.length === 0) {
        return { cards: [action.card] };
      }
      const newCards = [...state.cards];
      newCards[newCards.length - 1] = action.card;
      return { cards: newCards };
    }

    case 'RESET': {
      return { cards: action.cards };
    }

    case 'CLEAR': {
      return { cards: [] };
    }

    case 'UPDATE_PROPS': {
      const index = state.cards.findIndex((c) => c.id === action.id);
      if (index === -1) return state;

      const card = state.cards[index];
      const prevProps = (card.props ?? {}) as Record<string, unknown>;
      const newProps =
        typeof action.patch === 'function'
          ? (action.patch as (prev: unknown) => unknown)(card.props)
          : { ...prevProps, ...(action.patch as Record<string, unknown>) };

      const newCards = [...state.cards];
      newCards[index] = { ...card, props: newProps };
      return { cards: newCards };
    }

    case 'SET_TITLE': {
      const index = state.cards.findIndex((c) => c.id === action.id);
      if (index === -1) return state;

      const newCards = [...state.cards];
      newCards[index] = { ...newCards[index], title: action.title };
      return { cards: newCards };
    }

    case 'SET_DESCRIPTION': {
      const index = state.cards.findIndex((c) => c.id === action.id);
      if (index === -1) return state;

      const newCards = [...state.cards];
      newCards[index] = { ...newCards[index], description: action.description };
      return { cards: newCards };
    }

    case 'SET_WIDTH': {
      const index = state.cards.findIndex((c) => c.id === action.id);
      if (index === -1) return state;

      const newCards = [...state.cards];
      newCards[index] = { ...newCards[index], width: action.width };
      return { cards: newCards };
    }

    case 'SET_DISMISSABLE': {
      const index = state.cards.findIndex((c) => c.id === action.id);
      if (index === -1) return state;

      const newCards = [...state.cards];
      newCards[index] = { ...newCards[index], dismissable: action.dismissable };
      return { cards: newCards };
    }

    case 'DISMISS': {
      const index = state.cards.findIndex((c) => c.id === action.id);
      if (index === -1) return state;

      if (action.cascade) {
        // Cascade: remove this card and all cards above it
        return { cards: state.cards.slice(0, index) };
      } else {
        // No cascade: remove only this specific card
        return { cards: state.cards.filter((c) => c.id !== action.id) };
      }
    }

    case 'INSERT_AT': {
      const clampedIndex = Math.max(0, Math.min(action.index, state.cards.length));
      // Remove existing card with same ID
      const filtered = state.cards.filter((c) => c.id !== action.card.id);
      const newCards = [...filtered];
      newCards.splice(clampedIndex, 0, action.card);
      return { cards: newCards };
    }

    default:
      return state;
  }
}

// =============================================================================
// Context
// =============================================================================

const StackContext = createContext<StackContextValue | null>(null);

// =============================================================================
// Provider
// =============================================================================

export function CardStackProvider({
  children,
  routes = {},
  initial = [],
  onChange,
  zIndexBase = DEFAULT_Z_INDEX_BASE,
  layoutMode = 'cascade',
  defaultPeekOffset = DEFAULT_PEEK_OFFSET,
  defaultWidth = DEFAULT_WIDTH,
}: CardStackProviderProps) {
  const [state, reducerDispatch] = useReducer(stackReducer, { cards: initial });

  // Stable routes ref for API methods
  const routesRef = useRef(routes);
  useEffect(() => {
    routesRef.current = routes;
  }, [routes]);

  // State ref for API methods (avoid stale closures)
  const stateRef = useRef(state);
  useEffect(() => {
    stateRef.current = state;
  }, [state]);

  // Keep imperative reads current across multiple dispatches in the same event.
  const dispatch = React.useCallback(
    (action: StackAction) => {
      stateRef.current = stackReducer(stateRef.current, action);
      reducerDispatch(action);
    },
    [reducerDispatch],
  );

  // Track previous cards for onChange callback and onClose detection
  const prevCardsRef = useRef(state.cards);

  // Call onChange when cards change, and onClose for removed cards
  useEffect(() => {
    if (prevCardsRef.current !== state.cards) {
      const prevCards = prevCardsRef.current;
      const currentIds = new Set(state.cards.map((c) => c.id));

      // Find removed cards and call their onClose callbacks
      for (const card of prevCards) {
        if (!currentIds.has(card.id)) {
          card.onClose?.();
        }
      }

      prevCardsRef.current = state.cards;
      onChange?.(state.cards);
    }
  }, [state.cards, onChange]);

  // Build stable API object
  const api = useMemo<CardStackApi>(() => {
    // Read operations use stateRef to get current state
    const top = () => {
      const cards = stateRef.current.cards;
      return cards.length > 0 ? cards[cards.length - 1] : null;
    };

    const currentId = () => top()?.id ?? null;

    const canPop = () => stateRef.current.cards.length > 0;

    const size = () => stateRef.current.cards.length;

    const get = (id: CardId) => stateRef.current.cards.find((c) => c.id === id) ?? null;

    const getAll = () => [...stateRef.current.cards];

    const has = (id: CardId) => stateRef.current.cards.some((c) => c.id === id);

    // Navigation operations
    const push = <P,>(card: CardSpec<P>, options?: PushOptions) => {
      // If replaceFrom is specified, first remove all cards above that card
      if (options?.replaceFrom) {
        const fromIndex = stateRef.current.cards.findIndex((c) => c.id === options.replaceFrom);
        if (fromIndex !== -1 && fromIndex < stateRef.current.cards.length - 1) {
          // Pop cards above the 'from' card
          dispatch({ type: 'POP_TO', id: options.replaceFrom });
        }
      }
      dispatch({ type: 'PUSH', card: card as CardSpec });
      return card.id;
    };

    const pushRoute = <P,>(
      route: string,
      props?: P,
      opts?: { id?: CardId; title?: string; width?: string | number },
    ) => {
      const routeDef = routesRef.current[route];
      if (!routeDef) {
        throw new Error(`Stack: Route "${route}" not found in registry`);
      }

      const id = opts?.id ?? routeDef.getId?.(props) ?? route;
      const card: CardSpec<P> = {
        id,
        title: opts?.title ?? routeDef.defaultTitle,
        Component: routeDef.Component as CardSpec<P>['Component'],
        props,
        width: opts?.width ?? routeDef.defaultWidth,
        peekOffset: routeDef.defaultPeekOffset,
      };

      dispatch({ type: 'PUSH', card: card as CardSpec });
      return id;
    };

    const pop = (count = 1) => {
      dispatch({ type: 'POP', count });
    };

    const popTo = (id: CardId) => {
      dispatch({ type: 'POP_TO', id });
    };

    const replaceTop = <P,>(card: CardSpec<P>) => {
      dispatch({ type: 'REPLACE_TOP', card: card as CardSpec });
      return card.id;
    };

    const reset = (cards: CardSpec[]) => {
      dispatch({ type: 'RESET', cards });
    };

    const clear = () => {
      dispatch({ type: 'CLEAR' });
    };

    // Update operations
    const updateProps = <P,>(id: CardId, patch: Partial<P> | ((prev: P) => P)) => {
      dispatch({ type: 'UPDATE_PROPS', id, patch });
    };

    const setTitle = (id: CardId, title?: string) => {
      dispatch({ type: 'SET_TITLE', id, title });
    };

    const setDescription = (id: CardId, description?: string) => {
      dispatch({ type: 'SET_DESCRIPTION', id, description });
    };

    const setWidth = (id: CardId, width?: string | number) => {
      dispatch({ type: 'SET_WIDTH', id, width });
    };

    const setDismissable = (id: CardId, dismissable: boolean) => {
      dispatch({ type: 'SET_DISMISSABLE', id, dismissable });
    };

    // Advanced operations
    const dismiss = (id: CardId, options?: DismissOptions) => {
      const cascade = options?.cascade ?? true; // Default: cascade
      dispatch({ type: 'DISMISS', id, cascade });
    };

    const insertAt = <P,>(index: number, card: CardSpec<P>) => {
      dispatch({ type: 'INSERT_AT', index, card: card as CardSpec });
      return card.id;
    };

    return {
      top,
      currentId,
      canPop,
      size,
      get,
      getAll,
      has,
      push,
      pushRoute,
      pop,
      popTo,
      replaceTop,
      reset,
      clear,
      updateProps,
      setTitle,
      setDescription,
      setWidth,
      setDismissable,
      dismiss,
      insertAt,
    };
  }, [dispatch]);

  // Let nested controls and overlays handle Escape before dismissing the top card.
  useEffect(() => {
    const handleEscape = (event: KeyboardEvent) => {
      if (event.key === 'Escape' && !event.defaultPrevented && stateRef.current.cards.length > 0) {
        event.preventDefault();
        event.stopPropagation();
        const topCard = stateRef.current.cards[stateRef.current.cards.length - 1];
        if (topCard.dismissable !== false) {
          api.pop();
        }
      }
    };

    window.addEventListener('keydown', handleEscape);
    return () => window.removeEventListener('keydown', handleEscape);
  }, [api]);

  const contextValue = useMemo<StackContextValue>(
    () => ({
      state,
      api,
      config: {
        routes,
        zIndexBase,
        layoutMode,
        defaultPeekOffset,
        defaultWidth,
      },
    }),
    [state, api, routes, zIndexBase, layoutMode, defaultPeekOffset, defaultWidth],
  );

  return <StackContext.Provider value={contextValue}>{children}</StackContext.Provider>;
}

// =============================================================================
// Hooks
// =============================================================================

export function useCardStack(): CardStackApi {
  const context = useContext(StackContext);
  if (!context) {
    throw new Error('useCardStack must be used within a CardStackProvider');
  }
  return context.api;
}

export function useStackContext(): StackContextValue {
  const context = useContext(StackContext);
  if (!context) {
    throw new Error('useStackContext must be used within a CardStackProvider');
  }
  return context;
}

/** Hook to get current layout mode */
export function useStackLayoutMode(): LayoutMode {
  const context = useStackContext();
  return context.config.layoutMode;
}

/** Hook to get stack cards (triggers re-render on change) */
export function useStackCards(): CardSpec[] {
  const context = useStackContext();
  return context.state.cards;
}

/** Hook to check if a card is the top card */
export function useIsTopCard(id: CardId): boolean {
  const context = useStackContext();
  const cards = context.state.cards;
  return cards.length > 0 && cards[cards.length - 1].id === id;
}

/** Hook to get card index in stack */
export function useCardIndex(id: CardId): number {
  const context = useStackContext();
  return context.state.cards.findIndex((c) => c.id === id);
}

/** Create injected card props for a specific card */
export function useCardInjectedProps(id: CardId) {
  const api = useCardStack();

  return useMemo(
    () => ({
      card: {
        id,
        push: <P,>(
          card: Omit<CardSpec<P>, 'id'> & { id?: CardId },
          options?: CardPushOptions,
        ): CardId => {
          // Generate ID if not provided
          const cardId = card.id ?? `${id}-child-${Date.now()}`;
          const fullCard = { ...card, id: cardId } as CardSpec<P>;

          if (options?.append) {
            // Escape hatch: just push on top of the stack
            return api.push(fullCard);
          } else {
            // Default: replace cards above this card, then push
            return api.push(fullCard, { replaceFrom: id });
          }
        },
        close: () => api.dismiss(id),
        setTitle: (title?: string) => api.setTitle(id, title),
        setDescription: (description?: string) => api.setDescription(id, description),
        setWidth: (width?: string | number) => api.setWidth(id, width),
        setDismissable: (dismissable: boolean) => api.setDismissable(id, dismissable),
        updateProps: <P,>(patch: Partial<P> | ((prev: P) => P)) => api.updateProps(id, patch),
      },
    }),
    [id, api],
  );
}

// =============================================================================
// Card Ready Context - for deferring data loading until after animation
// =============================================================================

interface CardReadyContextValue {
  /** True when the card's enter animation has completed */
  isAnimationComplete: boolean;
}

const CardReadyContext = createContext<CardReadyContextValue | null>(null);

/** Provider for card animation state - used internally by StackCard */
export function CardReadyProvider({
  children,
  isAnimationComplete,
}: {
  children: React.ReactNode;
  isAnimationComplete: boolean;
}) {
  const value = useMemo(() => ({ isAnimationComplete }), [isAnimationComplete]);
  return <CardReadyContext.Provider value={value}>{children}</CardReadyContext.Provider>;
}

/**
 * Hook to check if the card's enter animation is complete.
 * Use this to defer data fetching until after the slide-in animation.
 *
 * @example
 * ```tsx
 * function MyCard() {
 *   const { isReady } = useCardReady();
 *
 *   // Data query that only runs after animation completes
 *   const { data, isLoading } = useQuery({
 *     queryKey: ['myData'],
 *     queryFn: fetchData,
 *     enabled: isReady, // Don't fetch until animation done
 *   });
 *
 *   return (
 *     <Select disabled={isLoading || !isReady}>
 *       {data?.map(item => <SelectItem key={item.id}>{item.name}</SelectItem>)}
 *     </Select>
 *   );
 * }
 * ```
 */
export function useCardReady(): { isReady: boolean } {
  const context = useContext(CardReadyContext);

  // If not in a card context (standalone usage), assume ready immediately
  if (!context) {
    return { isReady: true };
  }

  return { isReady: context.isAnimationComplete };
}

'use client';

import * as React from 'react';
import { memo, useMemo, useCallback, useState } from 'react';
import { motion, useReducedMotion } from 'motion/react';

import { cn } from '@/lib/utils';

import {
	createEnterTransition,
	createExitTransition,
	createOffsetTransition,
	peekHoverSpring,
	peekDragSpring,
} from '@/components/ui/stack/stack-animations';
import { CardReadyProvider, useCardInjectedProps, useStackContext } from '@/components/ui/stack/stack-context';
import { StackHeader } from '@/components/ui/stack/stack-header';
import type { AnimationConfig, CardSpec, CardStackApi, GestureConfig, PeekGestureConfig } from '@/components/ui/stack/stack.types';
import { getCardZIndex, getResponsiveCardOffset, normalizeWidth } from '@/components/ui/stack/stack-utils';
import { usePeekGestures } from '@/components/ui/stack/use-peek-gestures';
import type { StackGestureBind } from '@/components/ui/stack/use-stack-gestures';

/** Default hover expansion in pixels */
const DEFAULT_HOVER_EXPANSION = 48;
const reducedMotionTransition = { duration: 0 } as const;

export type StackCardProps = {
	/** The card specification */
	card: CardSpec;
	/** Index of this card in the stack */
	index: number;
	/** Total number of cards in the stack */
	totalCards: number;
	/** Width of the top card (for side-by-side calculations) */
	topCardWidth: number;
	/** Animation configuration */
	animation?: AnimationConfig;
	/** Whether this is a mobile viewport */
	isMobile?: boolean;
	/** Gesture configuration for mobile */
	gestureConfig?: GestureConfig;
	/** Peek gesture configuration */
	peekGestureConfig?: PeekGestureConfig;
	/** Custom header renderer */
	renderHeader?: (card: CardSpec, api: CardStackApi) => React.ReactNode;
	/** Compression ratio for responsive offset (1 = full, 0 = collapsed) */
	compressionRatio?: number;
	/** Adjusted peek offset after compression */
	adjustedPeekOffset?: number;
	/** Drag state from gesture hook (for top card swipe-to-dismiss) */
	dragX?: number;
	/** Gesture bind from @use-gesture/react */
	gestureBind?: StackGestureBind;
	/** Whether this card's peek zone is hovered (viewport-coordinated) */
	isPeekHovered?: boolean;
	/** Callback when peek hover starts */
	onPeekHoverStart?: (cardIndex: number) => void;
	/** Callback when peek hover ends */
	onPeekHoverEnd?: (cardIndex: number) => void;
	/** Peek drag offset applied to this card (when cards above are being dragged via peek zone) */
	peekDragOffset?: number;
	/** Callback when peek drag starts on this card's peek zone */
	onPeekDragStart?: (cardIndex: number) => void;
	/** Callback during peek drag on this card's peek zone */
	onPeekDrag?: (cardIndex: number, offset: number) => void;
	/** Callback when peek drag ends on this card's peek zone */
	onPeekDragEnd?: (cardIndex: number, shouldDismiss: boolean) => void;
	/** Whether this is the last card (for exit animation with fade) */
	isLastCard?: boolean;
	/** Additional class name for the card */
	className?: string;
};

function StackCardInner({
	card,
	index,
	totalCards,
	topCardWidth,
	animation,
	isMobile = false,
	renderHeader,
	peekGestureConfig,
	compressionRatio = 1,
	adjustedPeekOffset,
	dragX = 0,
	gestureBind,
	isPeekHovered = false,
	onPeekHoverStart,
	onPeekHoverEnd,
	peekDragOffset = 0,
	onPeekDragStart,
	onPeekDrag,
	onPeekDragEnd,
	isLastCard = false,
	className,
}: StackCardProps) {
	const { config, api, state } = useStackContext();
	const prefersReducedMotion = useReducedMotion();
	const injectedProps = useCardInjectedProps(card.id);

	// Track when enter animation completes - used by useCardReady() hook
	// Start true if reduced motion is preferred (no animation to wait for)
	const [isAnimationComplete, setAnimationComplete] = useState(prefersReducedMotion ?? false);

	// Handler for animation completion - fires when any animation on this element completes
	// The first animation to complete after mount is the enter animation
	const handleAnimationComplete = useCallback(() => {
		setAnimationComplete(true);
	}, []);

	// Calculate card positioning
	const isTopCard = index === totalCards - 1;
	const isSecondCard = index === totalCards - 2;
	// In side-by-side mode, second card is fully visible - no peek needed
	// Peek zone only for cards that are actually peeking (partially hidden under cards above)
	const hasPeekZone = !isTopCard && !isMobile && !(config.layoutMode === 'side-by-side' && isSecondCard);
	const zIndex = getCardZIndex(index, config.zIndexBase);

	// Use adjusted peek offset or default
	const effectivePeekOffset = adjustedPeekOffset ?? config.defaultPeekOffset;

	// Calculate responsive offset (compresses as viewport shrinks)
	const baseOffset = useMemo(
		() =>
			getResponsiveCardOffset(
				index,
				totalCards,
				state.cards,
				config.layoutMode,
				topCardWidth,
				effectivePeekOffset,
				compressionRatio,
				typeof config.defaultWidth === 'number' ? config.defaultWidth : 480,
			),
		[index, totalCards, state.cards, config.layoutMode, topCardWidth, effectivePeekOffset, compressionRatio, config.defaultWidth],
	);

	// Card width
	const cardWidth = isMobile ? '100%' : normalizeWidth(card.width, config.defaultWidth);

	// Animation transitions: enter/exit tweens, offset spring after settle
	const offsetTransition = createOffsetTransition(animation);
	const enterTransition = createEnterTransition(animation);
	const exitTransition = createExitTransition(animation);

	// Close handler
	const handleClose = useCallback(() => {
		api.dismiss(card.id);
	}, [api, card.id]);

	// Peek gesture callbacks
	const handlePeekClick = useCallback(() => {
		const cardsAbove = state.cards.slice(index + 1);
		if (cardsAbove.some((c) => c.dismissable === false)) return;
		api.popTo(card.id);
	}, [api, card.id, state.cards, index]);

	const handlePeekDragDismiss = useCallback(() => {
		const cardsAbove = state.cards.slice(index + 1);
		if (cardsAbove.some((c) => c.dismissable === false)) return;
		onPeekDragEnd?.(index, true);
	}, [index, onPeekDragEnd, state.cards]);

	const handlePeekDrag = useCallback(
		(offset: number) => {
			onPeekDrag?.(index, offset);
		},
		[index, onPeekDrag],
	);

	const handlePeekDragCancel = useCallback(() => {
		onPeekDragEnd?.(index, false);
	}, [index, onPeekDragEnd]);

	// Peek hover callbacks (forward to viewport)
	const handlePeekHoverStart = useCallback(() => {
		onPeekHoverStart?.(index);
	}, [index, onPeekHoverStart]);

	const handlePeekHoverEnd = useCallback(() => {
		onPeekHoverEnd?.(index);
	}, [index, onPeekHoverEnd]);

	// Peek gestures hook
	const peekGestures = usePeekGestures({
		...peekGestureConfig,
		cardIndex: index,
		totalCards,
		onPeekClick: handlePeekClick,
		onPeekDragDismiss: handlePeekDragDismiss,
		onPeekDrag: handlePeekDrag,
		onPeekDragCancel: handlePeekDragCancel,
	});

	// Calculate hover expansion using viewport-coordinated hover state
	const hoverExpansion = hasPeekZone && isPeekHovered && !peekGestures.isDragging && !prefersReducedMotion
		? (peekGestureConfig?.hoverExpansion ?? DEFAULT_HOVER_EXPANSION)
		: 0;

	// Combined X transform: base offset + swipe drag + hover expansion + peek drag from other cards
	// Note: peekDragOffset is applied when cards ABOVE this one are being dragged
	const xOffset = -baseOffset + dragX - hoverExpansion + peekDragOffset;

	// Render the card component with injected props, wrapped in CardReadyProvider
	const CardComponent = card.Component;
	const cardContent = useMemo(() => {
		return (
			<CardReadyProvider isAnimationComplete={isAnimationComplete}>
				<CardComponent {...(card.props as object)} {...injectedProps} />
			</CardReadyProvider>
		);
	}, [CardComponent, card.props, injectedProps, isAnimationComplete]);

	// Custom or default header
	const headerContent = renderHeader ? (
		renderHeader(card, api)
	) : (
		<StackHeader card={card} onClose={handleClose} />
	);

	// Animation states
	const animateX = xOffset;
	const initialX = prefersReducedMotion ? xOffset : '100%';
	const exitX = prefersReducedMotion ? xOffset : '100%';
	// Last card fades out as it slides for smoother exit when backdrop is also fading
	const exitOpacity = prefersReducedMotion ? 0 : (isLastCard ? 0 : 1);

	// Enter uses snappy tween until first settle; then spring for offset/peek.
	// Peek/drag always win while interacting.
	let activeTransition = prefersReducedMotion
		? reducedMotionTransition
		: isAnimationComplete
			? offsetTransition
			: enterTransition;
	if (!prefersReducedMotion) {
		if (peekGestures.isDragging || peekDragOffset > 0) {
			activeTransition = peekDragSpring;
		} else if (isPeekHovered) {
			activeTransition = peekHoverSpring;
		}
	}

	// Exit always honors the configured tween; reduced motion settles immediately.
	const exitAnimation = {
		x: exitX,
		opacity: exitOpacity,
		transition: prefersReducedMotion ? reducedMotionTransition : exitTransition,
	};

	return (
		<motion.div
			data-slot="stack-card"
			data-card-id={card.id}
			data-card-index={index}
			data-is-top={isTopCard}
			data-offset={baseOffset}
			initial={{ x: initialX, opacity: 1 }}
			animate={{ x: animateX, opacity: 1 }}
			exit={exitAnimation}
			transition={activeTransition}
			onAnimationComplete={handleAnimationComplete}
			style={{
				position: 'fixed',
				top: 0,
				right: 0,
				height: '100dvh',
				width: cardWidth,
				zIndex,
				// On mobile, allow vertical pan (scroll) but handle horizontal ourselves
				// This prevents conflict with iOS Safari gestures while allowing content scroll
				touchAction: isMobile ? 'pan-y pinch-zoom' : undefined,
			}}
			className={cn(
				'flex flex-col',
				'bg-background',
				'shadow-lg',
				'border-l border-border',
				className,
			)}
			// Gesture binding for swipe-to-dismiss (from @use-gesture/react)
			{...(isTopCard && isMobile && gestureBind ? gestureBind() : {})}
		>
			{/* Peek Zone - invisible overlay for gesture handling */}
			{hasPeekZone && (
				<div
					data-slot="peek-zone"
					className={cn(
						'absolute inset-y-0',
						'cursor-pointer',
						// Visual feedback during hover/drag (using viewport-coordinated state)
						isPeekHovered && 'bg-primary/5',
						peekGestures.isDragging && 'bg-primary/10',
					)}
					style={{
						// Peek zone covers the visible peek area (baseOffset determines how much is visible)
						// Minimum 32px, expands when hovered to keep mouse inside during animation
						left: 0,
						width: isPeekHovered
							? Math.max(32, baseOffset) + hoverExpansion
							: Math.max(32, baseOffset),
						zIndex: zIndex + 1,
						// Smooth transition to prevent sudden size jumps
						transition: 'width 0.15s ease-out',
					}}
					// Use viewport-coordinated hover + local gesture handlers
					onMouseEnter={handlePeekHoverStart}
					onMouseLeave={handlePeekHoverEnd}
					onClick={peekGestures.handlers.onClick}
					onPointerDown={peekGestures.handlers.onPointerDown}
					onPointerMove={peekGestures.handlers.onPointerMove}
					onPointerUp={peekGestures.handlers.onPointerUp}
					onPointerCancel={peekGestures.handlers.onPointerCancel}
				/>
			)}

			{/* Header */}
			{headerContent}

			{/* Content */}
			<div
				data-slot="stack-card-content"
				className="flex-1 overflow-auto"
				style={{
					// Allow vertical scroll but let us handle horizontal
					touchAction: isMobile ? 'pan-y pinch-zoom' : undefined,
				}}
				// Gesture binding also on content area (touch target is often inside here)
				{...(isTopCard && isMobile && gestureBind ? gestureBind() : {})}
			>
				{cardContent}
			</div>
		</motion.div>
	);
}

// Memoize to prevent re-renders when other cards change
export const StackCard = memo(StackCardInner);

'use client';

import * as React from 'react';
import { ChevronRight } from 'lucide-react';

import { cn } from '@/lib/utils';

import type { CardSpec } from '@/components/ui/stack/stack.types';

// =============================================================================
// Size Variants
// =============================================================================

type HeaderSize = 'sm' | 'md' | 'lg';

const sizeStyles = {
  sm: {
    title: 'text-sm font-semibold',
    description: 'text-xs',
    height: 'h-12',
    heightWithDesc: 'h-14',
  },
  md: {
    title: 'text-base font-semibold',
    description: 'text-sm',
    height: 'h-14',
    heightWithDesc: 'h-18',
  },
  lg: {
    title: 'text-lg font-semibold',
    description: 'text-sm',
    height: 'h-16',
    heightWithDesc: 'h-20',
  },
} satisfies Record<HeaderSize, { title: string; description: string; height: string; heightWithDesc: string }>;

// =============================================================================
// Component
// =============================================================================

export type StackHeaderProps = {
  /** The card spec */
  card: CardSpec;
  /** Close handler */
  onClose: () => void;
  /** Additional class names */
  className?: string;
  /** Custom title renderer */
  renderTitle?: (card: CardSpec) => React.ReactNode;
};

export function StackHeader({ card, onClose, className, renderTitle }: StackHeaderProps) {
  const title = renderTitle ? renderTitle(card) : card.title;
  const hasDescription = !!card.description;
  const size = card.headerSize ?? 'md';
  const styles = sizeStyles[size];

  return (
    <div
      data-slot="stack-header"
      className={cn(
        'flex shrink-0 items-center justify-between',
        'border-b border-border',
        'px-4',
        hasDescription ? styles.heightWithDesc : styles.height,
        className
      )}
    >
      {/* Title & Description */}
      <div className="flex-1 min-w-0">
        {title && (
          <h2 className={cn('text-foreground truncate', styles.title)} title={typeof title === 'string' ? title : undefined}>
            {title}
          </h2>
        )}
        {card.description && (
          <p className={cn('text-muted-foreground truncate', styles.description)} title={card.description}>
            {card.description}
          </p>
        )}
      </div>

      {/* Close button */}
      {card.dismissable !== false && (
        <button
          type="button"
          onClick={onClose}
          className={cn(
            'flex h-8 w-8 items-center justify-center',
            'rounded-md',
            'text-muted-foreground hover:text-foreground',
            'hover:bg-muted/50',
            'transition-[color,background-color,border-color,text-decoration-color,fill,stroke,box-shadow]',
            'focus-visible:outline-none focus-visible:ring-[3px] focus-visible:ring-ring/50'
          )}
          aria-label="Close"
        >
          <ChevronRight className="h-5 w-5" />
        </button>
      )}
    </div>
  );
}

export type StackHeaderSlotProps = {
  /** Additional class names */
  className?: string;
  children: React.ReactNode;
};

/** Slot for custom header content */
export function StackHeaderSlot({ className, children }: StackHeaderSlotProps) {
  return (
    <div
      data-slot="stack-header-slot"
      className={cn('flex h-12 shrink-0 items-center', 'border-b border-border', 'px-4', className)}
    >
      {children}
    </div>
  );
}

'use client';

import * as React from 'react';
import { motion, useReducedMotion } from 'motion/react';

import { cn } from '@/lib/utils';

import { backdropVariants, reducedMotionBackdropVariants } from '@/components/ui/stack/stack-animations';
import { useCardStack, useStackContext } from '@/components/ui/stack/stack-context';
import type { BackdropConfig } from '@/components/ui/stack/stack.types';

export type StackBackdropProps = {
	/** Additional class names */
	className?: string;
	/** Click handler (typically closes the stack) */
	onClick?: () => void;
	/** Backdrop configuration (blur, custom className) */
	config?: BackdropConfig;
};

export function StackBackdrop({ className, onClick, config: backdropConfig }: StackBackdropProps) {
	const { config, state } = useStackContext();
	const api = useCardStack();
	const prefersReducedMotion = useReducedMotion();

	const handleClick = React.useCallback(() => {
		if (state.cards.some((c) => c.dismissable === false)) return;
		if (onClick) {
			onClick();
		} else {
			// Default behavior: clear the entire stack
			api.clear();
		}
	}, [onClick, api, state.cards]);

	const variants = prefersReducedMotion ? reducedMotionBackdropVariants : backdropVariants;

	// Resolve backdrop styling - blur is off by default
	const useBlur = backdropConfig?.blur ?? false;

	return (
		<motion.div
			data-slot="stack-backdrop"
			variants={variants}
			initial="initial"
			animate="animate"
			exit="exit"
			onClick={handleClick}
			style={{ zIndex: config.zIndexBase - 1 }}
			className={cn(
				'fixed inset-0',
				'cursor-pointer',
				// Default overlay or custom className
				backdropConfig?.className ?? 'bg-black/32',
				// Optional blur
				useBlur && 'backdrop-blur-sm',
				className,
			)}
		/>
	);
}

'use client';

import * as React from 'react';
import { useMemo, useState, useCallback, useEffect, useRef } from 'react';
import { AnimatePresence } from 'motion/react';
import { createPortal } from 'react-dom';

import { cn } from '@/lib/utils';

import { PORTAL_ROOT_ID, useRootPortalContainer } from '@/components/ui/portal';

import { StackBackdrop } from '@/components/ui/stack/stack-backdrop';
import { StackCard } from '@/components/ui/stack/stack-card';
import { useStackCards, useStackContext } from '@/components/ui/stack/stack-context';
import type { BackdropConfig, CardStackViewportProps } from '@/components/ui/stack/stack.types';
import { useStackGestures } from '@/components/ui/stack/use-stack-gestures';
import { useStackResponsive } from '@/components/ui/stack/use-stack-responsive';
import {
	calculateResponsiveOffset,
	isCardVisible,
	parseWidthToPixels,
	type ResponsiveOffsetResult,
} from '@/components/ui/stack/stack-utils';

// =============================================================================
// Constants
// =============================================================================

const DEFAULT_PEEK_DEPTH = 2;
// =============================================================================
// Types
// =============================================================================

type PeekDragState = {
	/** Index of the card whose peek zone is being dragged (-1 = none) */
	sourceIndex: number;
	/** Current drag offset in pixels */
	offset: number;
};

type PeekHoverState = {
	/** Index of the card whose peek zone is hovered (-1 = none) */
	hoveredIndex: number;
};

// =============================================================================
// Component
// =============================================================================

export function CardStackViewport({
	backdrop = true,
	renderBackdrop,
	renderHeader,
	renderEmpty,
	peekDepth = DEFAULT_PEEK_DEPTH,
	animation,
	mobile,
	peekGestures,
	className,
}: CardStackViewportProps) {
	const { config, api } = useStackContext();
	const cards = useStackCards();

	// Responsive behavior
	const { isMobile, viewportWidth } = useStackResponsive(mobile);

	// Peek drag state - tracks which card's peek zone is being dragged
	const [peekDrag, setPeekDrag] = useState<PeekDragState>({ sourceIndex: -1, offset: 0 });

	// Peek hover state - only one card can be hovered at a time (viewport-coordinated)
	const [peekHover, setPeekHover] = useState<PeekHoverState>({ hoveredIndex: -1 });
	const hoverEndTimeoutRef = useRef<NodeJS.Timeout | null>(null);

	// Track previous card count to detect stack changes
	const prevCardCountRef = useRef(cards.length);

	// Track if exit animations have completed.
	// Key insight: This starts true (no animations pending when empty).
	// When cards appear, we set it to false (animations may be needed).
	// When cards disappear, it's still false from previous render, so AnimatePresence runs exits.
	// Only after onExitComplete fires do we set it back to true.
	const [exitComplete, setExitComplete] = useState(cards.length === 0);

	// When cards appear, mark exit as not complete (we have active content)
	useEffect(() => {
		if (cards.length > 0) {
			setExitComplete(false);
		}
	}, [cards.length]);

	// Clear hover state when stack changes (cards added/removed)
	useEffect(() => {
		if (cards.length !== prevCardCountRef.current) {
			// Stack changed - clear any hover state to prevent stale highlights
			setPeekHover({ hoveredIndex: -1 });
			// Also clear any pending hover-end timeout
			if (hoverEndTimeoutRef.current) {
				clearTimeout(hoverEndTimeoutRef.current);
				hoverEndTimeoutRef.current = null;
			}
			prevCardCountRef.current = cards.length;
		}
	}, [cards.length]);

	// Callback when all exit animations complete
	const handleExitComplete = useCallback(() => {
		setExitComplete(true);
	}, []);

	// Calculate card widths
	const cardWidths = useMemo(() => {
		if (cards.length === 0) return { topCardWidth: 0, secondCardWidth: 0 };

		const topCard = cards[cards.length - 1];
		const topCardWidth = parseWidthToPixels(topCard.width ?? config.defaultWidth) ?? 480;

		const secondCard = cards.length > 1 ? cards[cards.length - 2] : null;
		const secondCardWidth = secondCard
			? (parseWidthToPixels(secondCard.width ?? config.defaultWidth) ?? 480)
			: 0;

		return { topCardWidth, secondCardWidth };
	}, [cards, config.defaultWidth]);

	// Calculate responsive offset compression
	const responsiveOffset = useMemo<ResponsiveOffsetResult>(() => {
		return calculateResponsiveOffset({
			viewportWidth,
			topCardWidth: cardWidths.topCardWidth,
			secondCardWidth: cardWidths.secondCardWidth,
			totalCards: cards.length,
			defaultPeekOffset: config.defaultPeekOffset,
			layoutMode: config.layoutMode,
		});
	}, [viewportWidth, cardWidths, cards.length, config.defaultPeekOffset, config.layoutMode]);

	// Determine if we should use mobile/collapsed mode
	const useFullScreen = isMobile || responsiveOffset.shouldCollapse;

	// Gesture handling for top card swipe-to-dismiss
	const handleDismiss = useCallback(() => {
		const topCard = api.top();
		if (topCard?.dismissable === false) return;
		api.pop();
	}, [api]);

	// Use useFullScreen for gesture enabling (matches what we pass to cards)
	const swipeThreshold =
		mobile?.gestures?.swipeThreshold ?? Math.max(120, Math.round(viewportWidth * 0.35));
	const autoDismissThreshold =
		mobile?.gestures?.autoDismissThreshold ?? Math.max(swipeThreshold, Math.round(viewportWidth * 0.8));

	const { dragX, bind: gestureBind } = useStackGestures({
		enabled: useFullScreen && cards.length > 0,
		...mobile?.gestures,
		swipeThreshold,
		autoDismissThreshold,
		onDismiss: handleDismiss,
	});

	// Peek hover handlers - coordinate so only one card shows hover at a time
	const handlePeekHoverStart = useCallback((cardIndex: number) => {
		// Clear any pending hover-end timeout
		if (hoverEndTimeoutRef.current) {
			clearTimeout(hoverEndTimeoutRef.current);
			hoverEndTimeoutRef.current = null;
		}
		setPeekHover({ hoveredIndex: cardIndex });
	}, []);

	const handlePeekHoverEnd = useCallback((cardIndex: number) => {
		// Debounce hover-end to prevent flickering during animation
		if (hoverEndTimeoutRef.current) {
			clearTimeout(hoverEndTimeoutRef.current);
		}
		hoverEndTimeoutRef.current = setTimeout(() => {
			setPeekHover((prev) => (prev.hoveredIndex === cardIndex ? { hoveredIndex: -1 } : prev));
			hoverEndTimeoutRef.current = null;
		}, 100);
	}, []);

	// Peek drag handlers - coordinate multi-card animation
	const handlePeekDrag = useCallback((cardIndex: number, offset: number) => {
		setPeekDrag({ sourceIndex: cardIndex, offset });
	}, []);

	const handlePeekDragEnd = useCallback(
		(cardIndex: number, shouldDismiss: boolean) => {
			if (shouldDismiss) {
				// Check if any card above the dragged card is undismissable
				const cardsAbove = cards.slice(cardIndex + 1);
				if (cardsAbove.some((c) => c.dismissable === false)) {
					setPeekDrag({ sourceIndex: -1, offset: 0 });
					return;
				}
				// Pop all cards above the dragged card's peek zone
				const card = cards[cardIndex];
				if (card) {
					api.popTo(card.id);
				}
			}
			// Reset peek drag state
			setPeekDrag({ sourceIndex: -1, offset: 0 });
		},
		[api, cards],
	);

	// Determine which cards to render based on peekDepth
	const visibleCards = useMemo(() => {
		return cards.filter((_, index) => isCardVisible(index, cards.length, peekDepth));
	}, [cards, peekDepth]);

	// Portal container
	const portalContainer = useRootPortalContainer();

	// Content to render - keep AnimatePresence mounted for exit animations
	// Note: backdropNode is created inside render to access resolvedBackdrop
	const renderBackdropNode = (config?: BackdropConfig) => {
		const defaultBackdrop = <StackBackdrop key="backdrop" className="pointer-events-auto" config={config} />;
		if (renderBackdrop) {
			const customBackdrop = renderBackdrop();
			return React.isValidElement(customBackdrop)
				? React.cloneElement(customBackdrop, { key: 'backdrop' })
				: defaultBackdrop;
		}
		return defaultBackdrop;
	};

	// Track if we have cards (for backdrop and portal rendering)
	const hasCards = cards.length > 0;

	// Resolve backdrop config - first card takes precedence, then viewport prop
	// Returns: { enabled: boolean, config: BackdropConfig | undefined }
	const resolvedBackdrop = useMemo(() => {
		const firstCard = cards[0];
		const cardBackdrop = firstCard?.backdrop;

		// First card's backdrop setting takes precedence
		if (cardBackdrop !== undefined) {
			if (cardBackdrop === false) {
				return { enabled: false, config: undefined };
			}
			if (cardBackdrop === true) {
				return { enabled: true, config: undefined };
			}
			// Object config from card
			return { enabled: true, config: cardBackdrop as BackdropConfig };
		}

		// Fall back to viewport's backdrop prop
		if (backdrop === false) {
			return { enabled: false, config: undefined };
		}
		if (backdrop === true) {
			return { enabled: true, config: undefined };
		}
		// Object config from viewport
		return { enabled: true, config: backdrop as BackdropConfig };
	}, [cards, backdrop]);

	const shouldShowBackdrop = resolvedBackdrop.enabled;

	// Render nothing if no cards and exit animations are complete
	// This ensures AnimatePresence stays mounted during exit animations
	if (!hasCards && exitComplete) {
		return renderEmpty ? renderEmpty() : null;
	}

	const content = (
		<div data-slot="stack-viewport" className={cn('pointer-events-none fixed inset-0', className)}>
			{/* initial must stay true: viewport unmounts when empty, so first open remounts
			    AnimatePresence with cards already present. initial={false} skips enter. */}
			<AnimatePresence mode="popLayout" onExitComplete={handleExitComplete}>
				{/* Backdrop - only when cards exist and first card wants it */}
				{shouldShowBackdrop && hasCards && renderBackdropNode(resolvedBackdrop.config)}

				{/* Cards */}
				{visibleCards.map((card, visibleIndex) => {
					// Calculate actual index in full stack
					const actualIndex = cards.length - visibleCards.length + visibleIndex;
					const isTopCard = actualIndex === cards.length - 1;
					// Last card = only card in stack, used for exit animation with fade
					const isLastCard = cards.length === 1 && isTopCard;

					// Calculate peek drag offset for this card
					// Cards above the peek drag source get the drag offset applied
					const peekDragOffset =
						peekDrag.sourceIndex >= 0 && actualIndex > peekDrag.sourceIndex
							? peekDrag.offset
							: 0;

					return (
						<StackCard
							key={card.id}
							card={card}
							index={actualIndex}
							totalCards={cards.length}
							topCardWidth={cardWidths.topCardWidth}
							animation={animation}
							isMobile={useFullScreen}
							renderHeader={renderHeader}
							peekGestureConfig={peekGestures}
							// Responsive compression
							compressionRatio={responsiveOffset.compressionRatio}
							adjustedPeekOffset={responsiveOffset.adjustedPeekOffset}
							// Top card swipe-to-dismiss
							dragX={isTopCard ? dragX : 0}
							gestureBind={isTopCard ? gestureBind : undefined}
							// Peek hover coordination (viewport-level)
							isPeekHovered={peekHover.hoveredIndex === actualIndex}
							onPeekHoverStart={handlePeekHoverStart}
							onPeekHoverEnd={handlePeekHoverEnd}
							// Peek drag coordination
							peekDragOffset={peekDragOffset}
							onPeekDrag={handlePeekDrag}
							onPeekDragEnd={handlePeekDragEnd}
							// Last card exit animation (slide + fade)
							isLastCard={isLastCard}
							className="pointer-events-auto"
						/>
					);
				})}
			</AnimatePresence>
		</div>
	);

	// Render into portal if available, otherwise render in place
	if (portalContainer) {
		return createPortal(content, portalContainer);
	}

	return content;
}

'use client';

import { useEffect, useState } from 'react';

import { Skeleton } from '@/components/ui/skeleton';

export interface DeferredCardContentProps {
	children: React.ReactNode;
	/** Custom placeholder while waiting for animation to complete */
	placeholder?: React.ReactNode;
	/** Delay in ms before showing content (default: 220, slightly after 200ms animation) */
	delay?: number;
	/** Whether to show content immediately (useful for edit mode where data is cached) */
	immediate?: boolean;
	/**
	 * Priority level for scheduling content render:
	 * - 'high': Uses half the delay for faster content display
	 * - 'normal': Standard delay with rAF (default)
	 * - 'low': Uses requestIdleCallback when available for non-critical content
	 */
	priority?: 'high' | 'normal' | 'low';
	/** Callback when content becomes ready to render */
	onReady?: () => void;
}

/**
 * Defers rendering of heavy content until after Stack card animation completes.
 * This prevents layout thrashing and dropped frames during the slide-in animation.
 *
 * Usage:
 * ```tsx
 * <DeferredCardContent placeholder={<MySkeleton />}>
 *   <HeavyContent />
 * </DeferredCardContent>
 * ```
 *
 * With priority:
 * ```tsx
 * <DeferredCardContent priority="low" placeholder={<MySkeleton />}>
 *   <NonCriticalContent />
 * </DeferredCardContent>
 * ```
 */
export function DeferredCardContent({
	children,
	placeholder,
	delay = 220,
	immediate = false,
	priority = 'normal',
	onReady,
}: DeferredCardContentProps) {
	const [ready, setReady] = useState(immediate);

	useEffect(() => {
		if (immediate) {
			onReady?.();
			return;
		}

		let cancelled = false;

		const scheduleReady = () => {
			if (cancelled) return;
			setReady(true);
			onReady?.();
		};

		// Adjust delay based on priority
		const effectiveDelay = priority === 'high' ? Math.floor(delay / 2) : delay;

		// Use requestIdleCallback for low priority when available
		if (priority === 'low' && 'requestIdleCallback' in window) {
			const timeoutId = setTimeout(() => {
				const idleId = window.requestIdleCallback(scheduleReady, { timeout: effectiveDelay });
				return () => window.cancelIdleCallback(idleId);
			}, effectiveDelay);

			return () => {
				cancelled = true;
				clearTimeout(timeoutId);
			};
		}

		// Use setTimeout + rAF to sync with browser's paint cycle
		// This ensures content renders after animation settles
		const timeoutId = setTimeout(() => {
			const rafId = requestAnimationFrame(scheduleReady);
			return () => cancelAnimationFrame(rafId);
		}, effectiveDelay);

		return () => {
			cancelled = true;
			clearTimeout(timeoutId);
		};
	}, [delay, immediate, priority, onReady]);

	if (!ready) {
		return placeholder ?? <DefaultCardSkeleton />;
	}

	return <>{children}</>;
}

/**
 * Default skeleton placeholder for card content.
 * Shows a reasonable loading state for typical form-based cards.
 */
function DefaultCardSkeleton() {
	return (
		<div className="space-y-6 p-6">
			{/* Header area skeleton */}
			<div className="flex items-center justify-center py-4">
				<Skeleton className="h-24 w-48 rounded-lg" />
			</div>
			{/* Form field skeletons */}
			<div className="space-y-4">
				<div className="space-y-2">
					<Skeleton className="h-4 w-20" />
					<Skeleton className="h-10 w-full" />
				</div>
				<div className="space-y-2">
					<Skeleton className="h-4 w-16" />
					<Skeleton className="h-10 w-full" />
				</div>
				<div className="space-y-2">
					<Skeleton className="h-4 w-24" />
					<Skeleton className="h-10 w-full" />
				</div>
			</div>
		</div>
	);
}

