export const DEFAULT_ANIMATION_CONFIG: Required<AnimationConfig> = {
	duration: 0.2,
	enterEase: [0.32, 0.72, 0, 1], // Snappy entrance
	exitEase: [0.4, 0, 0.6, 1], // Physical exit
};

