/**
 * Create motion variants for card enter/exit animations.
 * Uses transform-only properties for GPU compositing.
 */
export function createCardVariants(config: AnimationConfig = {}): Variants {
	const { duration, enterEase, exitEase } = {
		...DEFAULT_ANIMATION_CONFIG,
		...config,
	};

	return {
		initial: {
			x: '100%',
		},
		animate: {
			x: 0,
			transition: {
				type: 'tween',
				duration,
				ease: enterEase as [number, number, number, number],
			},
		},
		exit: {
			x: '100%',
			transition: {
				type: 'tween',
				duration,
				ease: exitEase as [number, number, number, number],
			},
		},
	};
}

/**
 * Create transition for offset animations (when cards above change).
 * Uses spring for playful slide-back feel when cards are dismissed.
 */
export function createOffsetTransition(_config: AnimationConfig = {}): Transition {
	return {
		type: 'spring',
		stiffness: 300,
		damping: 30,
		mass: 0.8,
	};
}

/**
 * Enter transition for card slide-in (x: 100% → offset).
 * Tween + snappy ease — distinct from offset springs used after settle.
 */
export function createEnterTransition(config: AnimationConfig = {}): Transition {
	const { duration, enterEase } = {
		...DEFAULT_ANIMATION_CONFIG,
		...config,
	};

	return {
		type: 'tween',
		duration,
		ease: enterEase as [number, number, number, number],
	};
}

/**
 * Exit transition for card slide-out (offset → x: 100%).
 */
export function createExitTransition(config: AnimationConfig = {}): Transition {
	const { duration, exitEase } = {
		...DEFAULT_ANIMATION_CONFIG,
		...config,
	};

	return {
		type: 'tween',
		duration,
		ease: exitEase as [number, number, number, number],
	};
}

