import type { CardSpec, LayoutMode } from '@/components/ui/stack/stack.types';

// =============================================================================
// Offset Calculations
// =============================================================================

/**
 * Calculate the X offset for a card in cascade mode.
 * Cards below the top are pushed left by (cardsAbove * peekOffset).
 */
export function getCascadeOffset(
	cardIndex: number,
	totalCards: number,
	cards: CardSpec[],
	defaultPeekOffset: number,
): number {
	const cardsAbove = totalCards - cardIndex - 1;
	if (cardsAbove <= 0) return 0;

	// Use card-specific peekOffset if defined, else default
	const card = cards[cardIndex];
	const peekOffset = card?.peekOffset ?? defaultPeekOffset;

	return cardsAbove * peekOffset;
}

/**
 * Calculate the X offset for a card in side-by-side mode.
 * - Top card: no offset
 * - Second card: pushed by top card's width (fully visible side-by-side)
 * - Deeper cards: cascade further with peekOffset increments
 */
export function getSideBySideOffset(
	cardIndex: number,
	totalCards: number,
	topCardWidth: number,
	defaultPeekOffset: number,
): number {
	if (totalCards === 0) return 0;

	const cardsAbove = totalCards - cardIndex - 1;

	// Top card - no offset
	if (cardsAbove === 0) return 0;

	// Second card - pushed by top card width (side-by-side)
	if (cardsAbove === 1) return topCardWidth;

	// Deeper cards - cascade further
	const extraDepth = cardsAbove - 1;
	return topCardWidth + extraDepth * defaultPeekOffset;
}

/**
 * Get the offset for a card based on layout mode.
 */
export function getCardOffset(
	cardIndex: number,
	totalCards: number,
	cards: CardSpec[],
	layoutMode: LayoutMode,
	topCardWidth: number,
	defaultPeekOffset: number,
): number {
	if (layoutMode === 'side-by-side') {
		return getSideBySideOffset(cardIndex, totalCards, topCardWidth, defaultPeekOffset);
	}
	return getCascadeOffset(cardIndex, totalCards, cards, defaultPeekOffset);
}

// =============================================================================
// Responsive Offset Compression
// =============================================================================

/** Minimum visible peek for a card (in px) before it collapses - must be large enough to click */
const MIN_VISIBLE_PEEK = 24;

/** Padding from viewport edges */
const VIEWPORT_PADDING = 16;

export type ResponsiveOffsetConfig = {
	viewportWidth: number;
	topCardWidth: number;
	secondCardWidth: number;
	totalCards: number;
	defaultPeekOffset: number;
	layoutMode: LayoutMode;
};

export type ResponsiveOffsetResult = {
	/** Compression ratio (1 = full, 0 = fully compressed) */
	compressionRatio: number;
	/** Whether cards should collapse to mobile/single-card mode */
	shouldCollapse: boolean;
	/** Adjusted peek offset after compression */
	adjustedPeekOffset: number;
	/** Available space for peek offsets */
	availableSpace: number;
};

/**
 * Calculate responsive offset compression based on viewport width.
 * As viewport shrinks, offsets compress until hitting mobile breakpoint.
 *
 * The algorithm:
 * 1. Calculate space needed: topCardWidth + secondCardWidth (for side-by-side)
 * 2. Calculate available space: viewportWidth - padding
 * 3. If not enough space, compress the second card's offset
 * 4. When compression reaches threshold, trigger collapse to mobile
 */
export function calculateResponsiveOffset(config: ResponsiveOffsetConfig): ResponsiveOffsetResult {
	const {
		viewportWidth,
		topCardWidth,
		secondCardWidth,
		totalCards,
		defaultPeekOffset,
		layoutMode,
	} = config;

	// Available viewport space (with padding)
	const availableWidth = viewportWidth - VIEWPORT_PADDING * 2;

	if (totalCards <= 1) {
		return {
			compressionRatio: 1,
			shouldCollapse: false,
			adjustedPeekOffset: defaultPeekOffset,
			availableSpace: availableWidth,
		};
	}

	if (layoutMode === 'side-by-side') {
		// Side-by-side: we want both cards fully visible
		// Ideal: topCardWidth + secondCardWidth
		const idealWidth = topCardWidth + secondCardWidth;

		if (availableWidth >= idealWidth) {
			// Plenty of space - full side-by-side
			return {
				compressionRatio: 1,
				shouldCollapse: false,
				adjustedPeekOffset: defaultPeekOffset,
				availableSpace: availableWidth - topCardWidth,
			};
		}

		// Calculate how much we need to compress
		// The second card gets pushed under the top card
		const overflow = idealWidth - availableWidth;
		const maxCompression = secondCardWidth - MIN_VISIBLE_PEEK;

		if (overflow >= maxCompression) {
			// Not enough space even with full compression - collapse to mobile
			return {
				compressionRatio: 0,
				shouldCollapse: true,
				adjustedPeekOffset: 0,
				availableSpace: 0,
			};
		}

		// Compress the offset - second card slides under top card
		// compressionRatio: 1 = full visibility, 0 = collapsed
		const compressionRatio = 1 - overflow / maxCompression;
		const adjustedSecondCardVisible = secondCardWidth - overflow;

		return {
			compressionRatio,
			shouldCollapse: false,
			adjustedPeekOffset: defaultPeekOffset * compressionRatio,
			availableSpace: adjustedSecondCardVisible,
		};
	}

	// Cascade mode: calculate based on peek offsets
	const cascadeDepth = totalCards - 1;
	const totalPeekNeeded = cascadeDepth * defaultPeekOffset;
	const idealWidth = topCardWidth + totalPeekNeeded;

	if (availableWidth >= idealWidth) {
		return {
			compressionRatio: 1,
			shouldCollapse: false,
			adjustedPeekOffset: defaultPeekOffset,
			availableSpace: totalPeekNeeded,
		};
	}

	// Compress peek offsets proportionally
	const availableForPeek = Math.max(0, availableWidth - topCardWidth);
	const minPeekNeeded = cascadeDepth * MIN_VISIBLE_PEEK;

	if (availableForPeek < minPeekNeeded) {
		// Not enough space - collapse
		return {
			compressionRatio: 0,
			shouldCollapse: true,
			adjustedPeekOffset: 0,
			availableSpace: 0,
		};
	}

	// Calculate compressed peek offset
	const compressionRatio = availableForPeek / totalPeekNeeded;
	const adjustedPeekOffset = defaultPeekOffset * compressionRatio;

	return {
		compressionRatio,
		shouldCollapse: false,
		adjustedPeekOffset: Math.max(MIN_VISIBLE_PEEK, adjustedPeekOffset),
		availableSpace: availableForPeek,
	};
}

/**
 * Get responsive card offset that compresses based on viewport.
 * Ensures every card has at least MIN_VISIBLE_PEEK visible past cards above it.
 */
export function getResponsiveCardOffset(
	cardIndex: number,
	totalCards: number,
	cards: CardSpec[],
	layoutMode: LayoutMode,
	topCardWidth: number,
	adjustedPeekOffset: number,
	compressionRatio: number,
	defaultWidth: number = 480,
): number {
	if (totalCards === 0) return 0;

	const cardsAbove = totalCards - cardIndex - 1;
	if (cardsAbove === 0) return 0;

	if (layoutMode === 'side-by-side') {
		// Helper to get card width
		const getWidth = (idx: number): number => {
			const card = cards[idx];
			const w = card?.width;
			if (w === undefined) return defaultWidth;
			if (typeof w === 'number') return w;
			if (w.endsWith('px')) return parseFloat(w) || defaultWidth;
			return defaultWidth;
		};

		// Helper to get ideal offset for any card index (using standard side-by-side formula)
		const getIdealOffset = (idx: number): number => {
			const cardsAboveIdx = totalCards - idx - 1;
			if (cardsAboveIdx === 0) return 0;
			if (cardsAboveIdx === 1) return topCardWidth * compressionRatio + adjustedPeekOffset * (1 - compressionRatio);
			const extraDepth = cardsAboveIdx - 1;
			const secondOffset = topCardWidth * compressionRatio + adjustedPeekOffset * (1 - compressionRatio);
			return secondOffset + extraDepth * adjustedPeekOffset;
		};

		// Compute adjusted offsets for ALL cards from top to bottom
		// This ensures cards account for adjustments made to cards above them
		//
		// Coordinate system (from viewport right edge):
		// - Card at offset O with width W has: right edge at O, left edge at O + W
		// - For card's left peek (24px) to be visible past cardAbove:
		//   currentCard.leftEdge - MIN_VISIBLE_PEEK > cardAbove.leftEdge
		//   (currentOffset + currentWidth - MIN_VISIBLE_PEEK) > (aboveOffset + aboveWidth)
		//   currentOffset > aboveOffset + aboveWidth - currentWidth + MIN_VISIBLE_PEEK

		const adjustedOffsets: number[] = new Array(totalCards).fill(0);

		// Process from top card (highest index) to bottom card (index 0)
		for (let idx = totalCards - 1; idx >= 0; idx--) {
			const ideal = getIdealOffset(idx);
			const width = getWidth(idx);

			// Check if this card allows being covered (escape hatch)
			const cardAtIdx = cards[idx];
			const allowCover = cardAtIdx?.allowCover ?? false;

			if (allowCover) {
				adjustedOffsets[idx] = ideal;
				continue;
			}

			// Find minimum offset needed to peek past all cards above
			let minRequired = 0;
			for (let j = idx + 1; j < totalCards; j++) {
				// Use the ADJUSTED offset of cards above (already computed)
				const aboveLeftEdge = adjustedOffsets[j] + getWidth(j);
				const required = aboveLeftEdge - width + MIN_VISIBLE_PEEK;
				minRequired = Math.max(minRequired, required);
			}

			adjustedOffsets[idx] = Math.max(ideal, minRequired);
		}

		return adjustedOffsets[cardIndex];
	}

	// Cascade mode - use adjusted peek offset
	const card = cards[cardIndex];
	const peekOffset = card?.peekOffset ?? adjustedPeekOffset;
	return cardsAbove * peekOffset * compressionRatio + cardsAbove * MIN_VISIBLE_PEEK * (1 - compressionRatio);
}

// =============================================================================
// Width Utilities
// =============================================================================

/**
 * Normalize width to CSS value.
 */
export function normalizeWidth(width: string | number | undefined, defaultWidth: string | number): string {
	if (width === undefined) {
		return typeof defaultWidth === 'number' ? `${defaultWidth}px` : defaultWidth;
	}
	return typeof width === 'number' ? `${width}px` : width;
}

/**
 * Parse width to pixels (for offset calculations).
 * Returns undefined if width cannot be parsed to pixels.
 */
export function parseWidthToPixels(width: string | number | undefined): number | undefined {
	if (width === undefined) return undefined;
	if (typeof width === 'number') return width;

	// Handle px values
	if (width.endsWith('px')) {
		const parsed = parseFloat(width);
		return isNaN(parsed) ? undefined : parsed;
	}

	// Handle rem values (assume 16px base)
	if (width.endsWith('rem')) {
		const parsed = parseFloat(width);
		return isNaN(parsed) ? undefined : parsed * 16;
	}

	// Can't parse percentage or other values without DOM measurement
	return undefined;
}

// =============================================================================
// Z-Index Utilities
// =============================================================================

/**
 * Calculate z-index for a card based on its position in the stack.
 */
export function getCardZIndex(cardIndex: number, zIndexBase: number): number {
	return zIndexBase + cardIndex * 10;
}

// =============================================================================
// Visibility Utilities
// =============================================================================

/**
 * Determine which cards should be rendered based on peekDepth.
 * Returns indices of cards that should be rendered (from bottom to top).
 */
export function getVisibleCardIndices(totalCards: number, peekDepth: number): number[] {
	if (totalCards === 0) return [];

	// Always render the top card
	const startIndex = Math.max(0, totalCards - peekDepth - 1);
	const indices: number[] = [];

	for (let i = startIndex; i < totalCards; i++) {
		indices.push(i);
	}

	return indices;
}

/**
 * Check if a card should be rendered based on peekDepth.
 */
export function isCardVisible(cardIndex: number, totalCards: number, peekDepth: number): boolean {
	if (totalCards === 0) return false;
	const startIndex = Math.max(0, totalCards - peekDepth - 1);
	return cardIndex >= startIndex;
}

import type { ComponentType } from 'react';

// =============================================================================
// Core Types
// =============================================================================

export type CardId = string;

export type CardComponent<P = unknown> = ComponentType<P & CardInjectedProps>;

/** Configuration for the stack backdrop overlay */
export type BackdropConfig = {
	/** Enable backdrop blur effect (default: false) */
	blur?: boolean;
	/** Custom class name for full styling control */
	className?: string;
};

/** Props injected into every card component */
export type CardInjectedProps = {
	card: {
		id: CardId;
		/**
		 * Push a new card from this card.
		 * Default: replaces all cards above this card, then pushes the new card.
		 * Use { append: true } to just push on top of the entire stack.
		 */
		push: <P>(card: Omit<CardSpec<P>, 'id'> & { id?: CardId }, options?: CardPushOptions) => CardId;
		close: () => void;
		setTitle: (title?: string) => void;
		setDescription: (description?: string) => void;
		setWidth: (width?: string | number) => void;
		setDismissable: (dismissable: boolean) => void;
		updateProps: <P>(patch: Partial<P> | ((prev: P) => P)) => void;
	};
};

export type CardSpec<P = unknown> = {
	/** Unique identifier for this card instance */
	id: CardId;
	/** Display title in card header */
	title?: string;
	/** Display description/subtitle in card header */
	description?: string;
	/** Header size variant - controls title/description size, weight, and height */
	headerSize?: 'sm' | 'md' | 'lg';
	/** React component to render */
	Component: CardComponent<P>;
	/** Props passed to Component (excluding injected card props) */
	props?: P;
	/** Width override (CSS value) - default: 480px */
	width?: string | number;
	/** Custom peek offset for this card when cards stack above it (default: 24px) */
	peekOffset?: number;
	/**
	 * When true, this card can be fully covered by cards above it (no guaranteed peek).
	 * Use this escape hatch for cards where visibility isn't required when buried in stack.
	 * Default: false (card always peeks past cards above it)
	 */
	allowCover?: boolean;
	/**
	 * Show backdrop behind the stack when this card is the first card.
	 * Default: inherits from CardStackViewport's backdrop prop (true).
	 * Set to false for panel/sidebar-like cards that shouldn't obscure background.
	 * Pass an object to configure blur and styling.
	 */
	backdrop?: boolean | BackdropConfig;
	/** Whether user interactions (close button, Escape, backdrop click, gestures) can dismiss this card.
	 * Programmatic dismissal via card.close() / api.dismiss() always works. Default: true */
	dismissable?: boolean;
	/**
	 * Callback fired when this card is removed from the stack.
	 * Fires regardless of how the card was closed (swipe, backdrop, escape, api.dismiss, etc.)
	 */
	onClose?: () => void;
	/** Arbitrary metadata for analytics/debugging */
	meta?: Record<string, unknown>;
};

// =============================================================================
// Route Registry
// =============================================================================

export type CardRouteDefinition<P = unknown> = {
	/** Component to render for this route */
	Component: CardComponent<P>;
	/** Generate unique ID from props (default: route key) */
	getId?: (props?: P) => CardId;
	/** Default title for cards opened via this route */
	defaultTitle?: string;
	/** Default width for cards opened via this route */
	defaultWidth?: string | number;
	/** Default peek offset for cards opened via this route */
	defaultPeekOffset?: number;
};

export type CardRouteMap = Record<string, CardRouteDefinition<unknown>>;

// =============================================================================
// Layout Mode
// =============================================================================

export type LayoutMode = 'cascade' | 'side-by-side';

// =============================================================================
// Stack API
// =============================================================================

/** Options for dismiss operation */
export type DismissOptions = {
	/**
	 * When true (default), dismissing a card also dismisses all cards above it.
	 * When false, only the specified card is removed (escape hatch).
	 */
	cascade?: boolean;
};

/** Options for push operation */
export type PushOptions = {
	/**
	 * If provided, removes all cards above this card ID before pushing.
	 * Used internally by card.push() to implement replace-from-current behavior.
	 */
	replaceFrom?: CardId;
};

/** Options for push from within a card (injected card.push) */
export type CardPushOptions = {
	/**
	 * When true, just push on top of the entire stack (escape hatch).
	 * When false (default), replace cards above the current card first.
	 */
	append?: boolean;
};

export type CardStackApi = {
	// === Read Operations ===

	/** Get the topmost card spec, or null if empty */
	top: () => CardSpec | null;

	/** Get the ID of the topmost card, or null if empty */
	currentId: () => CardId | null;

	/** Check if stack has cards that can be popped */
	canPop: () => boolean;

	/** Get total number of cards in stack */
	size: () => number;

	/** Get a specific card by ID, or null if not found */
	get: (id: CardId) => CardSpec | null;

	/** Get all cards in stack (bottom to top order) */
	getAll: () => CardSpec[];

	/** Check if a specific card exists in the stack */
	has: (id: CardId) => boolean;

	// === Navigation Operations ===

	/**
	 * Push a new card onto the stack. Returns the card ID.
	 * Use { replaceFrom: cardId } to remove cards above that card first.
	 */
	push: <P>(card: CardSpec<P>, options?: PushOptions) => CardId;

	/** Push a card by registered route key. Returns the card ID. */
	pushRoute: <P>(
		route: string,
		props?: P,
		opts?: { id?: CardId; title?: string; width?: string | number },
	) => CardId;

	/** Pop one or more cards from the stack */
	pop: (count?: number) => void;

	/** Pop cards until the specified ID is on top */
	popTo: (id: CardId) => void;

	/** Replace the top card with a new one. Returns the new card ID. */
	replaceTop: <P>(card: CardSpec<P>) => CardId;

	/** Reset the entire stack to a specific set of cards */
	reset: (cards: CardSpec[]) => void;

	/** Clear all cards from the stack */
	clear: () => void;

	// === Card Updates ===

	/** Update props for a specific card */
	updateProps: <P>(id: CardId, patch: Partial<P> | ((prev: P) => P)) => void;

	/** Update the title for a specific card */
	setTitle: (id: CardId, title?: string) => void;

	/** Update the description for a specific card */
	setDescription: (id: CardId, description?: string) => void;

	/** Update the width for a specific card */
	setWidth: (id: CardId, width?: string | number) => void;

	/** Update the dismissable state for a specific card */
	setDismissable: (id: CardId, dismissable: boolean) => void;

	// === Advanced Operations ===

	/**
	 * Remove a card from the stack.
	 * By default (cascade: true), also removes all cards above it.
	 * Use { cascade: false } to remove only the specified card.
	 */
	dismiss: (id: CardId, options?: DismissOptions) => void;

	/** Insert a card at a specific index (0 = bottom) */
	insertAt: <P>(index: number, card: CardSpec<P>) => CardId;
};

// =============================================================================
// Provider Props
// =============================================================================

export type CardStackProviderProps = {
	children: React.ReactNode;
	/** Route registry for string-based navigation */
	routes?: CardRouteMap;
	/** Initial stack state */
	initial?: CardSpec[];
	/** Callback when stack changes */
	onChange?: (stack: CardSpec[]) => void;
	/** Z-index base for the stack (default: 100) */
	zIndexBase?: number;
	/**
	 * Layout mode for visible cards:
	 * - 'cascade': Cards peek behind each other with offset (default)
	 * - 'side-by-side': Second card pushed fully left, creating master-detail layout
	 */
	layoutMode?: LayoutMode;
	/** Default peek offset in pixels (default: 24) */
	defaultPeekOffset?: number;
	/** Default card width (default: 480) */
	defaultWidth?: string | number;
};

// =============================================================================
// Viewport Props
// =============================================================================

export type AnimationConfig = {
	/** Entry/exit duration in seconds (default: 0.2) */
	duration?: number;
	/** Entry easing (default: [0.32, 0.72, 0, 1]) */
	enterEase?: number[];
	/** Exit easing (default: [0.4, 0, 0.6, 1]) */
	exitEase?: number[];
};

export type GestureConfig = {
	/** Enable swipe-right-to-pop gesture (default: true on mobile) */
	swipeToPop?: boolean;
	/** Minimum swipe distance to trigger pop (default: 35% of viewport width, min 120px) */
	swipeThreshold?: number;
	/** Velocity threshold for quick swipe (default: 600px/s, requires minimum distance) */
	velocityThreshold?: number;
	/** Auto-dismiss X position while dragging (default: 80% of viewport width) */
	autoDismissThreshold?: number;
};

export type PeekGestureConfig = {
	/** Enable peek zone interactions (default: true) */
	enabled?: boolean;
	/** Enable drag-to-dismiss on peek zone (default: true) */
	dragToDismiss?: boolean;
	/** Hover expansion in pixels (default: 48) */
	hoverExpansion?: number;
	/** Minimum drag distance to trigger dismiss (default: 80px) */
	dragThreshold?: number;
	/** Velocity threshold for quick drag dismiss (default: 400px/s) */
	dragVelocityThreshold?: number;
};

export type MobileConfig = {
	/** Breakpoint for mobile behavior in pixels (default: 768) */
	breakpoint?: number;
	/** Force full-screen cards on mobile (default: true) */
	fullScreen?: boolean;
	/** Gesture configuration for mobile */
	gestures?: GestureConfig;
};

export type CardStackViewportProps = {
	/** Show backdrop behind first card (default: true). Pass object to configure blur/styling. */
	backdrop?: boolean | BackdropConfig;
	/** Custom backdrop element */
	renderBackdrop?: () => React.ReactNode;
	/** Custom header renderer per card */
	renderHeader?: (card: CardSpec, api: CardStackApi) => React.ReactNode;
	/** Custom empty state when stack is empty */
	renderEmpty?: () => React.ReactNode;
	/** Number of previous cards to render for peek effect (default: 2) */
	peekDepth?: number;
	/** Animation configuration */
	animation?: AnimationConfig;
	/** Mobile-specific configuration */
	mobile?: MobileConfig;
	/** Peek zone gesture configuration */
	peekGestures?: PeekGestureConfig;
	/** Additional class for viewport container */
	className?: string;
};

