'use client';

import { useState, useCallback, useRef } from 'react';
import { useDrag } from '@use-gesture/react';
import { useReducedMotion } from 'motion/react';

import type { GestureConfig } from '@/components/ui/stack/stack.types';

// =============================================================================
// Constants
// =============================================================================

/** Distance threshold to trigger dismiss */
const DEFAULT_SWIPE_THRESHOLD = 120; // px

/** Velocity threshold for quick flick dismiss */
const DEFAULT_VELOCITY_THRESHOLD = 0.6; // px/ms (use-gesture uses px/ms)

/** Minimum drag distance before velocity dismiss can apply */
const MIN_VELOCITY_DISTANCE = 60; // px

/** Left edge zone to ignore (avoid iOS Safari back gesture conflict) */
const EDGE_IGNORE_ZONE = 30; // px from left edge

// =============================================================================
// Types
// =============================================================================

export type UseStackGesturesOptions = GestureConfig & {
	/** Whether gestures are enabled */
	enabled?: boolean;
	/** Callback when swipe completes and should dismiss */
	onDismiss: () => void;
};

export type StackGestureBind = () => object;

export type UseStackGesturesResult = {
	/** Current drag X offset */
	dragX: number;
	/** Whether currently dragging */
	isDragging: boolean;
	/** Bind function to attach to the draggable element */
	bind: StackGestureBind;
};

// =============================================================================
// Hook
// =============================================================================

/**
 * Hook for swipe-to-dismiss gesture on stack cards using @use-gesture/react.
 *
 * Features:
 * - Only allows swiping to the right (positive X direction)
 * - Ignores touches near left edge (avoids iOS Safari back gesture conflict)
 * - Requires horizontal intent before activating (won't interfere with scroll)
 * - Dismisses on release after distance or velocity threshold
 * - Auto-dismisses near the end of the drag (configurable)
 * - 1:1 finger tracking for responsive feel
 */
export function useStackGestures(options: UseStackGesturesOptions): UseStackGesturesResult {
	const {
		enabled = true,
		swipeToPop = true,
		swipeThreshold = DEFAULT_SWIPE_THRESHOLD,
		velocityThreshold = DEFAULT_VELOCITY_THRESHOLD,
		autoDismissThreshold,
		onDismiss,
	} = options;


	const prefersReducedMotion = useReducedMotion();
	const isEnabled = enabled && swipeToPop && !prefersReducedMotion;

	const [dragX, setDragX] = useState(0);
	const [isDragging, setIsDragging] = useState(false);

	const handleDismiss = useCallback(() => {
		onDismiss();
	}, [onDismiss]);

	const dismissedRef = useRef(false);
	const velocityMinDistance = Math.max(MIN_VELOCITY_DISTANCE, swipeThreshold * 0.25);

	const bind = useDrag(
		({ active, movement: [mx], velocity: [vx], direction: [dx], initial: [initialX], xy: [currentX], cancel, first }) => {
			// On first event, check if touch started near left edge
			if (first && initialX < EDGE_IGNORE_ZONE) {
				cancel();
				return;
			}

			if (first) {
				dismissedRef.current = false;
			}

			// Only allow rightward movement (positive direction)
			// If user is dragging left, clamp to 0
			const clampedX = Math.max(0, mx);

			if (active) {
				const canAutoDismiss =
					autoDismissThreshold !== undefined &&
					!dismissedRef.current &&
					dx > 0 &&
					clampedX >= 24 &&
					currentX >= autoDismissThreshold;

				if (canAutoDismiss) {
					dismissedRef.current = true;
					setDragX(0);
					setIsDragging(false);
					handleDismiss();
					cancel();
					return;
				}

				setDragX(clampedX);
				setIsDragging(true);
				return;
			}

			if (!dismissedRef.current) {
				const shouldDismiss =
					dx > 0 &&
					(clampedX > swipeThreshold || (vx > velocityThreshold && clampedX > velocityMinDistance));

				if (shouldDismiss) {
					handleDismiss();
				}
			}

			// Reset state
			setDragX(0);
			setIsDragging(false);
		},
		{
			enabled: isEnabled,
			// Only activate after moving 10px (prevents accidental triggers)
			threshold: 10,
			// Lock to horizontal axis once gesture starts
			axis: 'x',
			// Filter by direction - only track if moving more horizontally than vertically
			filterTaps: true,
			// Use touch-action to allow vertical scroll
			pointer: {
				touch: true,
			},
		},
	);

	return {
		dragX,
		isDragging,
		bind,
	};
}

'use client';

import { useCallback, useRef, useState } from 'react';
import { useReducedMotion } from 'motion/react';

import type { PeekGestureConfig } from '@/components/ui/stack/stack.types';

// =============================================================================
// Constants
// =============================================================================

const DEFAULT_HOVER_EXPANSION = 48; // px
const DEFAULT_DRAG_THRESHOLD = 80; // px
const DEFAULT_VELOCITY_THRESHOLD = 400; // px/s

// =============================================================================
// Types
// =============================================================================

export type UsePeekGesturesOptions = PeekGestureConfig & {
	/** Card index in the stack */
	cardIndex: number;
	/** Total cards in stack */
	totalCards: number;
	/** Callback when click on peek zone (dismiss cards above) */
	onPeekClick: () => void;
	/** Callback when drag completes dismiss threshold */
	onPeekDragDismiss: () => void;
	/** Callback during drag to update multi-card offset */
	onPeekDrag?: (dragOffset: number) => void;
	/** Callback when drag ends without dismiss */
	onPeekDragCancel?: () => void;
};

export type UsePeekGesturesResult = {
	/** Whether peek zone is hovered */
	isHovered: boolean;
	/** Whether actively dragging */
	isDragging: boolean;
	/** Current drag offset (positive = dragging right/dismiss direction) */
	dragOffset: number;
	/** Hover expansion amount in px */
	hoverExpansion: number;
	/** Handlers for the peek zone element */
	handlers: {
		onMouseEnter: () => void;
		onMouseLeave: () => void;
		onClick: (e: React.MouseEvent) => void;
		onPointerDown: (e: React.PointerEvent) => void;
		onPointerMove: (e: React.PointerEvent) => void;
		onPointerUp: (e: React.PointerEvent) => void;
		onPointerCancel: (e: React.PointerEvent) => void;
	};
};

// =============================================================================
// Hook
// =============================================================================

/**
 * Hook for peek zone interactions: hover expansion, click-to-dismiss, drag-to-dismiss.
 * Works on both mobile and desktop.
 */
export function usePeekGestures(options: UsePeekGesturesOptions): UsePeekGesturesResult {
	const {
		enabled = true,
		dragToDismiss = true,
		hoverExpansion = DEFAULT_HOVER_EXPANSION,
		dragThreshold = DEFAULT_DRAG_THRESHOLD,
		dragVelocityThreshold = DEFAULT_VELOCITY_THRESHOLD,
		cardIndex,
		totalCards,
		onPeekClick,
		onPeekDragDismiss,
		onPeekDrag,
		onPeekDragCancel,
	} = options;

	const prefersReducedMotion = useReducedMotion();

	const [isHovered, setIsHovered] = useState(false);
	const [isDragging, setIsDragging] = useState(false);
	const [dragOffset, setDragOffset] = useState(0);

	// Tracking refs for drag
	const startXRef = useRef(0);
	const startTimeRef = useRef(0);
	const pointerIdRef = useRef<number | null>(null);
	const hasDraggedRef = useRef(false);

	// Only enable for non-top cards
	const isTopCard = cardIndex === totalCards - 1;
	const isEnabled = enabled && !isTopCard;

	// Handlers
	const handleMouseEnter = useCallback(() => {
		if (!isEnabled || prefersReducedMotion) return;
		setIsHovered(true);
	}, [isEnabled, prefersReducedMotion]);

	const handleMouseLeave = useCallback(() => {
		if (!isEnabled) return;
		setIsHovered(false);
	}, [isEnabled]);

	const handleClick = useCallback(
		(e: React.MouseEvent) => {
			if (!isEnabled) return;

			// Don't trigger click if we just finished dragging
			if (hasDraggedRef.current) {
				hasDraggedRef.current = false;
				return;
			}

			e.stopPropagation();
			onPeekClick();
		},
		[isEnabled, onPeekClick],
	);

	const handlePointerDown = useCallback(
		(e: React.PointerEvent) => {
			if (!isEnabled || !dragToDismiss) return;

			// Only handle primary pointer
			if (e.pointerType === 'mouse' && e.button !== 0) return;

			pointerIdRef.current = e.pointerId;
			(e.target as HTMLElement).setPointerCapture(e.pointerId);

			startXRef.current = e.clientX;
			startTimeRef.current = Date.now();
			hasDraggedRef.current = false;
			setIsDragging(true);

			e.stopPropagation();
		},
		[isEnabled, dragToDismiss],
	);

	const handlePointerMove = useCallback(
		(e: React.PointerEvent) => {
			if (!isEnabled || pointerIdRef.current !== e.pointerId) return;

			const deltaX = e.clientX - startXRef.current;

			// Only allow dragging to the right (positive = dismiss direction)
			const clampedDelta = Math.max(0, deltaX);

			// Mark as dragged if moved more than 5px (prevents accidental drags)
			if (clampedDelta > 5) {
				hasDraggedRef.current = true;
			}

			setDragOffset(clampedDelta);
			onPeekDrag?.(clampedDelta);

			e.stopPropagation();
		},
		[isEnabled, onPeekDrag],
	);

	const handlePointerUp = useCallback(
		(e: React.PointerEvent) => {
			if (!isEnabled || pointerIdRef.current !== e.pointerId) return;

			(e.target as HTMLElement).releasePointerCapture(e.pointerId);

			const deltaX = e.clientX - startXRef.current;
			const deltaTime = Date.now() - startTimeRef.current;
			const velocity = deltaTime > 0 ? (deltaX / deltaTime) * 1000 : 0;

			// Check if should dismiss
			const shouldDismiss = deltaX > dragThreshold || velocity > dragVelocityThreshold;

			if (shouldDismiss && deltaX > 0) {
				onPeekDragDismiss();
			} else {
				onPeekDragCancel?.();
			}

			// Reset state
			pointerIdRef.current = null;
			setIsDragging(false);
			setDragOffset(0);

			e.stopPropagation();
		},
		[isEnabled, dragThreshold, dragVelocityThreshold, onPeekDragDismiss, onPeekDragCancel],
	);

	const handlePointerCancel = useCallback(
		(e: React.PointerEvent) => {
			if (pointerIdRef.current === e.pointerId) {
				pointerIdRef.current = null;
				setIsDragging(false);
				setDragOffset(0);
				onPeekDragCancel?.();
			}
		},
		[onPeekDragCancel],
	);

	return {
		isHovered,
		isDragging,
		dragOffset,
		hoverExpansion: isEnabled && !prefersReducedMotion ? hoverExpansion : 0,
		handlers: {
			onMouseEnter: handleMouseEnter,
			onMouseLeave: handleMouseLeave,
			onClick: handleClick,
			onPointerDown: handlePointerDown,
			onPointerMove: handlePointerMove,
			onPointerUp: handlePointerUp,
			onPointerCancel: handlePointerCancel,
		},
	};
}

'use client';

import { useCallback, useEffect, useState } from 'react';

import type { MobileConfig } from '@/components/ui/stack/stack.types';

// =============================================================================
// Constants
// =============================================================================

const DEFAULT_MOBILE_BREAKPOINT = 768;

// =============================================================================
// Hook
// =============================================================================

export type UseStackResponsiveOptions = MobileConfig;

export type UseStackResponsiveResult = {
	/** Whether the current viewport is mobile-sized */
	isMobile: boolean;
	/** Current viewport width */
	viewportWidth: number;
	/** The breakpoint being used */
	breakpoint: number;
};

/**
 * Hook to detect mobile viewport and provide responsive information.
 */
export function useStackResponsive(
	options: UseStackResponsiveOptions = {},
): UseStackResponsiveResult {
	const { breakpoint = DEFAULT_MOBILE_BREAKPOINT } = options;

	// Initialize with SSR-safe defaults
	const [state, setState] = useState<{ isMobile: boolean; viewportWidth: number }>(() => {
		// During SSR, assume desktop
		if (typeof window === 'undefined') {
			return { isMobile: false, viewportWidth: 1024 };
		}
		const width = window.innerWidth;
		return { isMobile: width < breakpoint, viewportWidth: width };
	});

	const updateState = useCallback(() => {
		const width = window.innerWidth;
		setState((prev) => {
			const isMobile = width < breakpoint;
			if (prev.isMobile === isMobile && prev.viewportWidth === width) {
				return prev;
			}
			return { isMobile, viewportWidth: width };
		});
	}, [breakpoint]);

	useEffect(() => {
		// Update on mount (in case SSR assumption was wrong)
		updateState();

		// Listen for resize
		window.addEventListener('resize', updateState);
		return () => window.removeEventListener('resize', updateState);
	}, [updateState]);

	return {
		isMobile: state.isMobile,
		viewportWidth: state.viewportWidth,
		breakpoint,
	};
}

/**
 * Simple hook to just get isMobile boolean.
 */
export function useIsMobile(breakpoint = DEFAULT_MOBILE_BREAKPOINT): boolean {
	const { isMobile } = useStackResponsive({ breakpoint });
	return isMobile;
}
